insert into public.places(city_id,name,place_type,categories,price_note,address,lat,lng,schedule,description,style_tags,status,last_confirmed_at)select c.id,v.n,v.t,v.c,v.p,v.a,v.la,v.lo,v.s,v.d,v.tags,'approved',now() from public.cities c cross join(values('Культторг','flea_zone',array['flea','home','antiques']::text[],'Разные цены — демо','Казань, адрес уточнить',55.7900,49.1000,'Уточнить','Тестовая запись; адрес и актуальность требуют проверки.','барахолка'),('Комиссионка — пример','shop',array['clothes','home']::text[],'Средний бюджет','Казань — демо',55.8000,49.1200,'Уточнить','Тестовое место для UI.','комиссионка'),('Jevrejska — кластер секондов','cluster_street',array['clothes','flea']::text[],'Разные цены','Jevrejska, Novi Sad, Serbia',45.2550,19.8460,'Уточнить','Кластер секондов; состав точек проверить.','секонды'),('Винтаж — демо','shop',array['antiques','home']::text[],'Средний / высокий','Нови-Сад — демо',45.2600,19.8400,'Уточнить','Тестовая карточка, адрес не подтверждён.','винтаж'))v(n,t,c,p,a,la,lo,s,d,tags)where c.slug in('kazan','novi-sad')and not exists(select 1 from public.places x where x.city_id=c.id and x.name=v.n);
insert into public.online_markets(country,city_id,name,url,categories,guide_text,requires_local_phone,has_delivery)select 'Россия',c.id,'Авито','https://www.avito.ru',array['clothes','home','media','antiques','flea'],'Уточняйте состояние, торг, самовывоз и доставку.',false,true from public.cities c where c.slug='kazan' and not exists(select 1 from public.online_markets where name='Авито');
insert into public.online_markets(country,city_id,name,url,categories,guide_text,requires_local_phone,has_delivery)select 'Сербия',c.id,'KupujemProdajem','https://www.kupujemprodajem.com',array['clothes','home','media','antiques','flea'],'Поиск: polovno, vintage, antikviteti. Доставку согласуйте с продавцом.',true,true from public.cities c where c.slug='novi-sad' and not exists(select 1 from public.online_markets where name='KupujemProdajem');
insert into public.finds(item_name,price_paid,currency,category)select 'Демо-улов: керамическая ваза',450,'₽','home' where not exists(select 1 from public.finds where item_name='Демо-улов: керамическая ваза');
insert into public.finds(item_name,price_paid,currency,category)select 'Демо-улов: винтажная куртка',1800,'RSD','clothes' where not exists(select 1 from public.finds where item_name='Демо-улов: винтажная куртка');